--region handler
---cell点击回调
function OverseaStoreSkinCell:BtnNodeOnClickHandler()
    if CardSkinComponent:IsHasSkin(self._cellData.icon) then
        -- 已拥有
        GameUtils.Toast(localize("皮肤已拥有"))
        return
    end

    xRecord.record("5-011", string.format('click_skin_%d', checkInt(self._cellData.icon))) 
    OverseaStoreMgr:OpenBuyItemDialog(self._cellData, self._storeType)
end

---详情按钮点击回调
function OverseaStoreSkinCell:BtnCheckOnClickHandler()
    UIModule.OpenDialog(
            {
                id = Constants.UITypeIds.CommonStylePreView,
                parameters = {skinId = self._cellData.icon},
            },
            {
                {id = Constants.UITypeIds.OverseaStore}
            }
    )
end
--endregion handler

--region public
---@param storeType OverseaStoreConstants.StoreType
---@param data table 
function OverseaStoreSkinCell:RefreshCell(storeType, data)
    self._storeType = storeType
    self._cellData = data
    if type(self._cellData.payPoint) == "function" then
        self._cellData.payPoint = nil
    end
    if type(self._cellData.price) == "function" then
        self._cellData.price = nil
    end

    self:RefreshCellState(data)
    self:RefreshTimeGroup(data)
    self:RefreshSkin(data)
    self:RefreshPrice(data)
end

---更新剩余时间显示
function OverseaStoreSkinCell:UpdateTimeGroupText(data)
    local seconds = checkInt(data.endTime)
    if seconds <= 0 then return end

    if checkInt(data.iconId) == TagType.Discount or checkInt(data.iconId) == TagType.All then
        CfUtils.FillText(self.DiscountSymbol2TxtTime, CfUtils.GetTimeHMS10(seconds))
    else
        CfUtils.FillText(self.TextDay, CfUtils.GetTimeHMS4(seconds))
    end
end

