--region private
---刷新cell状态
function OverseaStoreSkinCell:RefreshCellState(data)
    if CardSkinComponent:IsHasSkin(data.icon) then
        -- 已拥有
        KTool.SetActive(self.Price, false)
        KTool.SetActive(self.None, true)
        KTool.SetActive(self.DisableMask, true)
        KTool.SetActive(self.ImgSold, true)
        KTool.SetActive(self.UIFX_StoreStyle, false)
        return
    end

    KTool.SetActive(self.Price, true)
    KTool.SetActive(self.None, false)
    KTool.SetActive(self.DisableMask, false)
    KTool.SetActive(self.UIFX_StoreStyle, true)
end

---刷新剩余时间
function OverseaStoreSkinCell:RefreshTimeGroup(data)
    local seconds = checkInt(data.endTime)
    if seconds <= 0 then
        CfUtils.SetActive(self.TimeNode, false)
        CfUtils.SetActive(self.DiscountSymbol2, false)
        return
    end

    local iconId = checkInt(data.iconId)
    if iconId == TagType.Discount or iconId == TagType.All then
        CfUtils.SetActive(self.DiscountSymbol2, true)
        CfUtils.SetActive(self.TimeNode, false)
    else
        CfUtils.SetActive(self.TimeNode, true)
        CfUtils.SetActive(self.DiscountSymbol2, false)
    end
    
    self:UpdateTimeGroupText(data)
end

---刷新皮肤
function OverseaStoreSkinCell:RefreshSkin(data)
    local skinVo = CardConfMgr:GetInstance():GetCardSkinBySkinId(data.icon)
    if not skinVo then return end

    local cardSkinVo = CfUtils.GetCfVo(AutoIds.IdSetting113, "CardSkinVo", skinVo.skinId)
    local ActivityUtils = import("Game.Activity.ActivityUtils")
    CfUtils.FillImage(self.ImgRole, ActivityUtils.GetImageFullPath(data.image ,false))
    CfUtils.FillText(self.TextName, skinVo.name)
    local skinRare = cardSkinVo:GetRare()
    CfUtils.SetUISwitchImage(self.ImgQuality, skinRare)
    CfUtils.SetUISwitchImage(self.UIFX_StoreStyleGlow, skinRare)
    CfUtils.SetUISwitchParticleSystem(self.UIFX_StoreStyleLiuGuang, skinRare)
    CfUtils.SetActive(self.ImgInteract, IdolLive3D_Utils.GetLive3DCardVoRow(skinVo.skinId) and true or false)

    if string.isEmpty(cardSkinVo.version) then
        CfUtils.SetActive(self.ImgBrand, false)
    else
        CfUtils.SetActive(self.ImgBrand, true)
        CfUtils.FillImage(self.ImgBrand, cardSkinVo.version)
    end
end

---刷新价格
function OverseaStoreSkinCell:RefreshPrice(data)
    if checkInt(data.price) > 0 then
        -- 货币购买
        if checkInt(data.original) ~= 0 then
            CfUtils.SetActive(self.Price2, true)
            CfUtils.SetActive(self.Price2ImgIcon, false)
            CfUtils.FillText(self.Price2TextOriginal, CfUtils.GetCustomDisplayPrice(data.original, nil, 30))
            CfUtils.SetUISwitchText(self.Price2TextOriginal, 1)
        else
            CfUtils.SetActive(self.Price2, false)
        end
        CfUtils.SetActive(self.DisCurrentPriceImgIcon, false)
        local windowsPriceId =  CfUtils.GetWindowsPriceId(data)
        CfUtils.FillText(self.DisTextNumber, CfUtils.GetCustomDisplayPrice(windowsPriceId , data.channelProductId, 26))
        CfUtils.SetUISwitchImage(self.Animation, 1)
    else
        local goodsId = checkNumber(data.prices[1].currency)
        if goodsId == Constants.Currency.PayDiamondId then
            CfUtils.SetUISwitchImage(self.Animation, 1)
        else
            CfUtils.SetUISwitchImage(self.Animation, 2)
        end
        local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
        if checkInt(data.prices[1].original) ~= 0 then
            CfUtils.SetActive(self.Price2, true)
            CfUtils.SetActive(self.Price2ImgIcon, true)
            CfUtils.FillImage(self.Price2ImgIcon, goodsVo.photoPath)
            CfUtils.FillText(self.Price2TextOriginal, data.prices[1].original)
            CfUtils.SetUISwitchText(self.Price2TextOriginal, 2)
        else
            CfUtils.SetActive(self.Price2, false)
        end
        CfUtils.SetActive(self.DisCurrentPriceImgIcon, true)
        CfUtils.FillImage(self.DisCurrentPriceImgIcon, goodsVo.photoPath)
        CfUtils.FillText(self.DisTextNumber, data.prices[1].current)
        --CfUtils.SetUISwitchImage(self.Animation, 2)
    end
    
    local tabType = checkInt(data.iconId)
    if tabType == TagType.Discount then
        KTool.SetActive(self.ActivityTabelGroup, false)
        
        if checkInt(data.endTime) > 0 then
            CfUtils.SetActive(self.DiscountSymbolTime, true)
            CfUtils.SetActive(self.DiscountSymbol, false)
            CfUtils.FillText(self.TxtDiscount, localize("限时_num_折", {_num_ = data.iconTitle}))
        else
            CfUtils.SetActive(self.DiscountSymbol, true)
            CfUtils.FillText(self.DiscountTxtNumber, data.iconTitle)
            CfUtils.SetActive(self.DiscountSymbolTime, false)
        end
        
    elseif tabType == TagType.Recommend then
        KTool.SetActive(self.DiscountSymbol, false)
        KTool.SetActive(self.ActivityTabelGroup, true)
    elseif tabType == TagType.All then
        KTool.SetActive(self.ActivityTabelGroup, true)
        if checkInt(data.endTime) > 0 then
            CfUtils.SetActive(self.DiscountSymbolTime, true)
            CfUtils.SetActive(self.DiscountSymbol, false)
            CfUtils.FillText(self.TxtDiscount, localize("限时_num_折", {_num_ = data.iconTitle}))
        else
            CfUtils.SetActive(self.DiscountSymbol, true)
            CfUtils.FillText(self.DiscountTxtNumber, data.iconTitle)
            CfUtils.SetActive(self.DiscountSymbolTime, false)
        end
    else
        KTool.SetActive(self.DiscountSymbol, false)
        KTool.SetActive(self.ActivityTabelGroup, false)
        CfUtils.SetActive(self.DiscountSymbolTime, false)
    end
end
--endregion private

return OverseaStoreSkinCell